import { z } from 'zod';
import { UuidSchema, TimestampSchema } from '../common/schemas.js';
import { SkillScoreSchema, PathwayAffinitySchema } from '../intelligence/schemas.js';

/**
 * Individual section of the 13-part SparkTrack Development Report.
 * Each section has a key, title, and free-form content generated by Gemini.
 */
export const ReportSectionSchema = z.object({
  key: z.string(),
  title: z.string(),
  /** AI-generated narrative content (Gemini synthesis) */
  narrative: z.string(),
  /** Supporting data points used in synthesis */
  supportingData: z.record(z.unknown()).optional(),
  /** Confidence score for this section (0-1) */
  confidence: z.number().min(0).max(1).optional(),
});
export type ReportSection = z.infer<typeof ReportSectionSchema>;

/**
 * Non-Deterministic Guardrail validation result.
 *
 * The guardrail scans report text for deterministic career assignment
 * phrases and rejects reports that violate the exploration philosophy.
 *
 * FORBIDDEN patterns:
 *   - "You are going to become..."
 *   - "You should be a..."
 *   - "Your career is..."
 *   - "You are destined to..."
 *
 * REQUIRED patterns:
 *   - "exploration", "pathway worth exploring", "growing signals"
 *   - "current evidence shows...", "one area to explore further..."
 */
export const NonDeterministicGuardrailSchema = z.object({
  passed: z.boolean(),
  /** Any deterministic phrases found (should be empty for passing reports) */
  deterministicViolations: z.array(
    z.object({
      phrase: z.string(),
      sectionKey: z.string(),
      severity: z.enum(['CRITICAL', 'WARNING']),
    }),
  ),
  /** Count of exploration-positive language found */
  explorationLanguageCount: z.number().int().min(0),
  /** Minimum required exploration phrases */
  minimumRequired: z.number().int().default(3),
});
export type NonDeterministicGuardrailResult = z.infer<typeof NonDeterministicGuardrailSchema>;

/**
 * The 13-Part SparkTrack Development Report.
 *
 * Generated by the RecommendationEngine using LangGraph.js + Gemini.
 * This is the core deliverable viewed by parents and schools.
 */
export const DevelopmentReportSchema = z.object({
  /** Unique report ID */
  id: UuidSchema,
  learnerId: UuidSchema,
  /** Report version (increments each regeneration) */
  version: z.number().int().min(1),
  /** When this report was generated */
  generatedAt: TimestampSchema,
  /** The timestamp the capability profile was snapshotted at */
  profileSnapshotAt: TimestampSchema,

  // ===== THE 13 SECTIONS =====

  /** Section 1: Executive Summary & Learner Identity */
  executiveSummary: ReportSectionSchema,

  /** Section 2: Programme Participation History */
  participationHistory: ReportSectionSchema,

  /** Section 3: Declared Interests vs. Observed Strengths Analysis */
  declaredVsObserved: ReportSectionSchema,

  /** Section 4: Technical & Digital Skills Assessment */
  technicalSkills: ReportSectionSchema,

  /** Section 5: Creative & Design Skills Assessment */
  creativeSkills: ReportSectionSchema,

  /** Section 6: Business & Entrepreneurship Skills Assessment */
  businessSkills: ReportSectionSchema,

  /** Section 7: Behavioural Signals & Developmental Indicators */
  behaviouralSignals: ReportSectionSchema,

  /** Section 8: Capability Maturity Analysis */
  capabilityMaturity: ReportSectionSchema,

  /** Section 9: Career Pathway Exploration Map */
  careerPathways: ReportSectionSchema,

  /** Section 10: Entrepreneurship Pathway Exploration Map */
  entrepreneurshipPathways: ReportSectionSchema,

  /** Section 11: Longitudinal Progress & Growth Trajectory */
  longitudinalProgress: ReportSectionSchema,

  /** Section 12: Recommended Next Steps & Exploration Areas */
  recommendedNextSteps: ReportSectionSchema,

  /** Section 13: Mentor Observations & Qualitative Insights */
  mentorInsights: ReportSectionSchema,

  // ===== METADATA =====

  /** Raw skill scores used in generation */
  skillScores: z.array(SkillScoreSchema),

  /** Pathway affinities used in generation */
  pathwayAffinities: z.array(PathwayAffinitySchema),

  /** Non-deterministic guardrail validation result */
  guardrailResult: NonDeterministicGuardrailSchema,

  /** Model used for synthesis */
  synthesisModel: z.string(),

  /** Cache key for Redis caching */
  cacheKey: z.string().optional(),
});
export type DevelopmentReport = z.infer<typeof DevelopmentReportSchema>;
